parameters.jsCode:
// Log the 4xx rejection without retrying.
// 4xx means the request was structurally invalid (bad signature, duplicate,
// unsupported event). Retrying will never help — log and drop cleanly.
const statusCode = $input.first().json.statusCode || 'unknown';
const body = JSON.stringify($input.first().json.body || $input.first().json);
console.log(`[Flow-A] Cal.com webhook rejected by AxonFlow API. Status: ${statusCode}. Body: ${body}. Not retried.`);
return [{ json: { logged: true, statusCode, body } }];

